// new NazwaKlasy(...) wykonuje cztery kroki:
// 1. JavaScript tworzy nowy, pusty obiekt
// 2. Wywoluje constructor klasy, ustawiajac this wewnatrz niego na ten
//    nowo utworzony obiekt
// 3. Kod wewnatrz konstruktora (np. this.pole = wartosc) ustawia pola
//    na tym nowym obiekcie
// 4. Nowy obiekt (z ustawionymi polami) jest zwracany z new i mozna go
//    przypisac do zmiennej - ma teraz dostep do wszystkich metod
//    zdefiniowanych w klasie

class Prostokat {
  constructor(szer, wys) {
    this.szer = szer;
    this.wys = wys;
  }

  pole() {
    return this.szer * this.wys;
  }

  obwod() {
    return 2 * (this.szer + this.wys);
  }
}

const p = new Prostokat(3, 4);
console.log(p.pole());  // -> 12
console.log(p.obwod()); // -> 14

class Konto {
  constructor(saldo = 0) {
    this.saldo = saldo;
  }

  wplac(kwota) {
    this.saldo += kwota;
  }

  wyplac(kwota) {
    if (kwota > this.saldo) return false;
    this.saldo -= kwota;
    return true;
  }
}

const konto = new Konto(100);
konto.wplac(50);
console.log(konto.wyplac(30));  // -> true
console.log(konto.wyplac(500)); // -> false
console.log(konto.saldo);       // -> 120
console.log(new Konto().saldo); // -> 0

