class Wektor {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  czyRowny(inny) {
    return this.x === inny.x && this.y === inny.y;
  }
}

const a = new Wektor(1, 2);
const b = new Wektor(1, 2);
console.log(a.czyRowny(b)); // -> true
