class Stos {
  constructor() {
    this.elementy = [];
  }

  dodaj(x) {
    this.elementy.push(x);
  }

  zdejmij() {
    return this.elementy.pop();
  }

  podejrzyj() {
    return this.elementy[this.elementy.length - 1];
  }

  rozmiar() {
    return this.elementy.length;
  }
}

const s = new Stos();
s.dodaj(1);
s.dodaj(2);
s.dodaj(3);
console.log(s.zdejmij());   // -> 3
console.log(s.podejrzyj()); // -> 2
console.log(s.rozmiar());   // -> 2

class Temperatura {
  constructor(celsjusz) {
    this.celsjusz = celsjusz;
  }

  naFahrenheita() {
    return (this.celsjusz * 9) / 5 + 32;
  }

  naKelwina() {
    return this.celsjusz + 273.15;
  }
}

const t = new Temperatura(100);
console.log(t.naFahrenheita()); // -> 212
console.log(t.naKelwina());     // -> 373.15

class Zawodnik {
  constructor(imie) {
    this.imie = imie;
    this.wyniki = [];
  }

  dodajWynik(w) {
    this.wyniki.push(w);
  }

  srednia() {
    if (this.wyniki.length === 0) return 0;
    const suma = this.wyniki.reduce((s, x) => s + x, 0);
    return suma / this.wyniki.length;
  }
}

const z = new Zawodnik("Ala");
console.log(z.srednia()); // -> 0
z.dodajWynik(8);
z.dodajWynik(10);
console.log(z.srednia()); // -> 9

class Kolejka {
  constructor() {
    this.elementy = [];
  }

  dodaj(x) {
    this.elementy.push(x);
  }

  pobierz() {
    return this.elementy.shift();
  }

  pusta() {
    return this.elementy.length === 0;
  }
}

const k = new Kolejka();
k.dodaj("a");
k.dodaj("b");
console.log(k.pobierz()); // -> "a"
console.log(k.pobierz()); // -> "b"
console.log(k.pusta());   // -> true

class Punkt {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
}

function stworz(Klasa, ...args) {
  return new Klasa(...args);
}

const p = stworz(Punkt, 1, 2);
console.log(p.x, p.y); // -> 1 2
// new: (1) tworzy pusty obiekt, (2) ustawia jego prototyp na Klasa.prototype,
// (3) wywoluje constructor z this rownym temu obiektowi, (4) zwraca obiekt.

